def is_valid_vpa(s):
    # Define the regex pattern for a valid VPA
    pattern = r'^[a-zA-Z0-9._-]{2,256}@[a-zA-Z0-9.-]{2,64}$'

    # Use the re.match function to check if the string matches the pattern
    return bool(re.match(pattern, s))

