def late_fee(days_late, daily_fee, cap):
    """
    Calculate the late fee based on days_late, daily_fee, and cap.

    :param days_late: int, number of days late
    :param daily_fee: int, late fee per day in rupees
    :param cap: int, maximum total late fee cap
    :return: int, late fee
    """
    if days_late <= 0:
        return 0
    else:
        return min(days_late * daily_fee, cap)

